using System;
using System.Collections.Generic;
using System.Linq;
using Avalonia.Media;

namespace Prism.Controls;

public sealed record IconShape(Geometry Geometry, IBrush? Fill, IPen? Stroke);

/// <summary>
/// Hand-drawn two-tone vector icons on a 32x32 grid. Each shape is "fill|stroke|width|path"
/// where fill/stroke are palette letters (or #RRGGBB) and '-' means none.
/// </summary>
public static class Icons
{
    // the neutral inks swap with the theme so the same drawing reads on a dark or a light panel
    static readonly Dictionary<char, string> LightInk = new() { ['k'] = "#2B3648", ['s'] = "#6B7A92", ['S'] = "#C3CCDA", ['w'] = "#F2F5FA" };
    static bool Light => Avalonia.Application.Current?.ActualThemeVariant == Avalonia.Styling.ThemeVariant.Light;

    static readonly Dictionary<char, string> Pal = new()
    {
        ['k'] = "#D3DDEC", ['s'] = "#8D9DB5", ['S'] = "#3E4A5F", ['w'] = "#2B3342",
        ['b'] = "#2F66C9", ['B'] = "#79A8F2", ['m'] = "#4C86E0", ['d'] = "#9CC4FF",
        ['o'] = "#FFB02E", ['O'] = "#7A5A22", ['g'] = "#3FCF8E", ['G'] = "#1F5A43",
        ['r'] = "#FF6B6F", ['R'] = "#6A2E33", ['t'] = "#2BC4D1", ['T'] = "#1D5C63",
        ['p'] = "#B79CFF", ['P'] = "#5A4AA0",
    };

    static readonly Dictionary<string, IconShape[]> Cache = [];
    static readonly Dictionary<string, IconShape[]> CacheLight = [];

    public static IconShape[]? Get(string? name)
    {
        if (name == null) return null;
        bool light = Light; var cache = light ? CacheLight : Cache;
        if (cache.TryGetValue(name, out var c)) return c;
        if (!Defs.TryGetValue(name, out var def)) return null;
        return cache[name] = def.Select(s => Parse(s, light)).ToArray();
    }

    static IBrush? Brush(string s, bool light = false) => s == "-" ? null : new SolidColorBrush(Color.Parse(s.Length == 1 ? (light && LightInk.TryGetValue(s[0], out var li) ? li : Pal[s[0]]) : s));

    static IconShape Parse(string spec, bool light)
    {
        var p = spec.Split('|');
        var fill = Brush(p[0], light);
        var stroke = p[1] == "-" ? null : new Pen(Brush(p[1], light), double.Parse(p[2], System.Globalization.CultureInfo.InvariantCulture), lineCap: PenLineCap.Round, lineJoin: PenLineJoin.Round);
        return new IconShape(Geometry.Parse(p[3]), fill, stroke);
    }

