        [$"{left}|k|1|M{tr}", $"{right}|k|1|M{tr}", $"{top}|k|1|M{tr}"];

    static string Arrow(string d, char c = 'o') => $"-|{c}|2.4|{d}";
    static string Head(string d, char c = 'o') => $"{c}|{c}|1|{d}";

